<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { Plus, Search } from '@element-plus/icons-vue'
import { api } from '../api'
import { state, refresh, vehicle, mask, labels, dateText, today, overdue } from '../store'
import FormDialog from '../components/FormDialog.vue'
import StatusTag from '../components/StatusTag.vue'
import VehicleIdentity from '../components/VehicleIdentity.vue'
const query = reactive({ search: '', category: '', restricted: '' }), page = ref(1), open = ref(false), detail = ref(null), edit = ref(null), initial = ref({}), busy = ref(false)
const filtered = computed(() => state.customers.filter(item => (!query.search || `${item.name}${item.phone}`.includes(query.search)) && (!query.category || item.category === query.category) && (query.restricted === '' || query.restricted == null || item.restricted === query.restricted)))
watch(query, () => page.value = 1)
const fields = [{ key: 'name', label: '客户姓名' }, { key: 'phone', label: '联系电话', maxlength: 20 }, { key: 'identity_no', label: '身份证 / 证件号', tip: '课程演示请使用虚构编号，如 DEMO-ID-000010' }, { key: 'license_no', label: '驾驶证编号' }, { key: 'license_expiry', label: '驾驶证有效期', type: 'date' }, { key: 'category', label: '客户类别', type: 'select', options: [{ label: '普通客户', value: 'NORMAL' }, { label: '会员客户', value: 'VIP' }] }, { key: 'restricted', label: '限制租赁', type: 'switch', required: false }, { key: 'notes', label: '备注 / 限制原因', type: 'textarea', wide: true, required: false, maxlength: 500 }]
function create(customer) { edit.value = customer?.id || null; initial.value = customer ? { ...customer } : { category: 'NORMAL', restricted: false }; open.value = true }
async function save(data) { busy.value = true; try { const result = await api[edit.value ? 'put' : 'post']('/customers' + (edit.value ? '/' + edit.value : ''), data); open.value = false; await refresh(); if (detail.value?.id === result.id) detail.value = result; ElMessage.success('客户资料已保存') } catch {} finally { busy.value = false } }
const history = computed(() => state.orders.filter(order => order.customer_id === detail.value?.id))
const credit = computed(() => ({ overdue: history.value.filter(order => overdue(order) || (order.actual_end && order.actual_end > order.planned_end)).length, damage: history.value.filter(order => order.damage).length, completed: history.value.filter(order => order.status === 'COMPLETED').length }))
</script>

<template>
  <div class="module-overview"><div><strong>{{ state.customers.length }}</strong><span>客户档案</span></div><div><strong class="text-accent">{{ state.customers.filter(item => item.category === 'VIP').length }}</strong><span>会员客户</span></div><div><strong>{{ state.customers.filter(item => item.restricted).length }}</strong><span>限制租赁</span></div><div><strong>{{ state.customers.filter(item => item.license_expiry < today()).length }}</strong><span>驾驶证已过期</span></div><el-button type="primary" :icon="Plus" @click="create()">新增客户</el-button></div>
  <section class="panel listing-panel"><div class="filter-bar"><el-input v-model="query.search" :prefix-icon="Search" placeholder="搜索姓名、联系方式" clearable class="search-input"/><el-select v-model="query.category" placeholder="全部类别" clearable><el-option label="普通客户" value="NORMAL"/><el-option label="会员客户" value="VIP"/></el-select><el-select v-model="query.restricted" placeholder="全部租赁资格" clearable><el-option label="正常" :value="false"/><el-option label="限制租赁" :value="true"/></el-select></div><div class="listing-caption"><span>客户档案 <small>{{ filtered.length }} 位</small></span><span>证件与联系方式脱敏展示 · 仅使用虚构演示数据</span></div><el-table :data="filtered.slice((page - 1) * 10, page * 10)"><el-table-column label="客户" min-width="145"><template #default="{ row }"><div class="person-cell"><span class="avatar customer-avatar">{{ row.name.slice(-2) }}</span><div><strong>{{ row.name }}</strong><small class="cell-sub">编号 C{{ String(row.id).padStart(4, '0') }}</small></div></div></template></el-table-column><el-table-column label="联系方式" min-width="130"><template #default="{ row }">{{ mask(row.phone) }}</template></el-table-column><el-table-column label="证件号" min-width="145"><template #default="{ row }">{{ mask(row.identity_no) }}</template></el-table-column><el-table-column label="驾驶证有效期" min-width="130"><template #default="{ row }"><span :class="{ 'text-danger': row.license_expiry < today() }">{{ row.license_expiry }}</span></template></el-table-column><el-table-column label="类别" width="110"><template #default="{ row }"><span :class="['category-tag', { vip: row.category === 'VIP' }]">{{ labels[row.category] }}</span></template></el-table-column><el-table-column label="租赁资格" width="110"><template #default="{ row }"><span :class="row.restricted ? 'text-danger' : 'text-green'">{{ row.restricted ? '限制租赁' : '正常' }}</span></template></el-table-column><el-table-column label="操作" width="125"><template #default="{ row }"><el-button link type="primary" @click="detail = row">详情</el-button><el-button link type="primary" @click="create(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ filtered.length }} 位客户</span><el-pagination v-model:current-page="page" :page-size="10" :total="filtered.length" layout="prev, pager, next"/></div></section>
  <FormDialog v-model="open" :title="edit ? '编辑客户资料' : '登记新客户'" :fields="fields" :initial="initial" :busy="busy" @submit="save"/>
  <el-drawer :model-value="!!detail" @close="detail = null" title="客户档案" size="580px"><template v-if="detail"><div class="profile-heading"><span class="avatar large-avatar">{{ detail.name.slice(-2) }}</span><h2>{{ detail.name }}</h2><span class="category-tag">{{ labels[detail.category] }}</span><el-tag v-if="detail.restricted" type="danger">限制租赁</el-tag></div><el-descriptions :column="1" border><el-descriptions-item label="联系电话">{{ mask(detail.phone) }}</el-descriptions-item><el-descriptions-item label="身份证号">{{ mask(detail.identity_no) }}</el-descriptions-item><el-descriptions-item label="驾驶证号">{{ mask(detail.license_no) }}</el-descriptions-item><el-descriptions-item label="驾驶证有效期">{{ detail.license_expiry }}</el-descriptions-item><el-descriptions-item label="备注">{{ detail.notes || '无' }}</el-descriptions-item></el-descriptions><div class="credit-grid"><div><strong>{{ credit.completed }}</strong><span>正常完成</span></div><div><strong>{{ credit.overdue }}</strong><span>逾期记录</span></div><div><strong>{{ credit.damage }}</strong><span>损坏记录</span></div></div><h3 class="section-title">历史租赁订单</h3><el-table :data="history"><el-table-column prop="order_no" label="订单编号" min-width="160"/><el-table-column label="车辆" min-width="235"><template #default="{ row }"><VehicleIdentity :vehicle="vehicle(row.vehicle_id)"/></template></el-table-column><el-table-column label="租赁日期" min-width="160"><template #default="{ row }">{{ dateText(row.planned_start) }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column></el-table></template></el-drawer>
</template>
